{-# LANGUAGE DataKinds         #-}
{-# LANGUAGE DeriveGeneric     #-}
{-# LANGUAGE DeriveTraversable #-}
{-# LANGUAGE FlexibleContexts  #-}
{-# LANGUAGE FlexibleInstances #-}
{-# LANGUAGE GADTs             #-}
{-# LANGUAGE KindSignatures    #-}
{-# LANGUAGE LambdaCase        #-}
{-# LANGUAGE PatternSynonyms   #-}
{-# LANGUAGE RankNTypes        #-}
{-# LANGUAGE TemplateHaskell   #-}
{-# LANGUAGE TypeFamilies      #-}
{-# OPTIONS_GHC -Wno-missing-signatures -Wno-redundant-constraints -Wno-orphans #-}
-- | Scope-safe syntax of the monolithic language, generated by free-foil's
-- Template Haskell from "Monolith.Raw": the signature @TermSig@, the term
-- type @Term@, the pattern type @Pattern@ with one constructor for one name
-- and one for two, the pattern synonyms @Lam@, @App@ and so on, and the
-- conversions @toTerm@ and @fromTerm@. The generated names are the raw ones,
-- so the raw syntax is imported qualified.
module Monolith.Generated where

import qualified Control.Monad.Foil as Foil
import Control.Monad.Free.Foil (AST (..))
import Control.Monad.Free.Foil.TH.MkFreeFoil
import Data.ZipMatchK
import Generics.Kind.TH (deriveGenericK)

import qualified Monolith.Raw as Raw
import Monolith.Syntax.Print (printTree)

-- The identifier's instance comes first, since the generated 'ZipMatchK'
-- instance of the signature needs it in the same declaration group.
instance ZipMatchK Raw.VarIdent where zipMatchWithK = zipMatchViaEq

mkFreeFoil Raw.config

{-# COMPLETE Var, Lam, App, Pi, Pair, Fst, Snd, Split, Zero, Suc, NatRec #-}

deriveGenericK ''Pattern
instance Foil.SinkableK Pattern
instance Foil.HasNameBinders Pattern
instance Foil.UnifiablePattern Pattern

mkFreeFoilConversions Raw.config

-- | Terms print through the raw conversion and BNFC's printer. Variables are
-- named by foil identifier, so the output re-parses but is not α-canonical.
instance Show (AST Pattern TermSig n) where
  show = printTree . fromTerm
